package com.fincore.fincore.budget; import java.util.List; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.fincore.fincore.exception.*; import com.fincore.fincore.user.UserRepository; @Service public class BudgetService{private final BudgetRepository budgets;private final UserRepository users;public BudgetService(BudgetRepository b,UserRepository u){budgets=b;users=u;}@Transactional public BudgetResponse create(Long uid,CreateBudgetRequest r){if(budgets.findByUserIdAndCategoryIgnoreCaseAndMonth(uid,r.category(),r.month().atDay(1)).isPresent())throw new ConflictException("Budget already exists for this category and month");var u=users.findById(uid).orElseThrow(()->new NotFoundException("User not found"));return BudgetResponse.from(budgets.save(new Budget(r.category().trim(),r.amount(),r.month().atDay(1),u)));}@Transactional(readOnly=true)public List<BudgetResponse> all(Long uid){return budgets.findAllByUserIdOrderByMonthDesc(uid).stream().map(BudgetResponse::from).toList();}@Transactional public BudgetResponse update(Long uid,Long id,UpdateBudgetRequest r){var b=budgets.findByIdAndUserId(id,uid).orElseThrow(()->new NotFoundException("Budget not found"));b.setAmount(r.amount());return BudgetResponse.from(b);}@Transactional public void delete(Long uid,Long id){var b=budgets.findByIdAndUserId(id,uid).orElseThrow(()->new NotFoundException("Budget not found"));budgets.delete(b);}}
